import 'package:pdf/widgets.dart' as pw;

Future<pw.Document> buildSimplePdf() async {
  final pdf = pw.Document();
  pdf.addPage(
    pw.Page(
      build: (context) => pw.Center(
        child: pw.Text('Hello PDF!'),
      ),
    ),
  );
  return pdf;
}

import 'dart:io';
import 'package:path_provider/path_provider.dart';
import 'package:pdf/widgets.dart' as pw;

Future<File> savePdf(pw.Document pdf) async {
  final dir = await getApplicationDocumentsDirectory();
  final file = File('${dir.path}/report.pdf');
  await file.writeAsBytes(await pdf.save());
  return file;
}

import 'package:pdf/widgets.dart' as pw;

Future<pw.Document> buildInvoice() async {
  final pdf = pw.Document();
  pdf.addPage(
    pw.Page(
      build: (context) => pw.Column(
        crossAxisAlignment: pw.CrossAxisAlignment.start,
        children: [
          pw.Text('주문서', style: pw.TextStyle(fontSize: 24)),
          pw.SizedBox(height: 16),
          pw.Table.fromTextArray(
            headers: ['항목', '수량', '가격'],
            data: [
              ['상품A', '2', '10,000원'],
              ['상품B', '1', '5,000원'],
            ],
          ),
          pw.SizedBox(height: 16),
          pw.Text('총 합계: 25,000원'),
        ],
      ),
    ),
  );
  return pdf;
}

import 'package:printing/printing.dart';
import 'package:pdf/widgets.dart' as pw;

Future<void> previewPdf(pw.Document pdf) async {
  await Printing.layoutPdf(
    onLayout: (format) async => pdf.save(),
  );
}
